__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'adrianna.pienkowska@nokia.com, justyna.gacek@nokia.com'

from datetime import datetime


class Table:
    def __init__(self, worksheet, systime, data):
        self.worksheet = worksheet
        self.systime = systime
        self.data = data

        self._columns_not_nested = None
        self._columns_nested = []
        self._rows_amount = None
        self._is_nested_dictionary = True

    @property
    def rows_amount(self):
        return self._rows_amount

    @property
    def values(self):
        """
        Gives number of column or list of numbers depending on nested dictionary.
        """
        if self._is_nested_dictionary:
            return self._columns_nested
        else:
            return self._columns_not_nested

    @property
    def is_nested_dictionary(self):
        return self._is_nested_dictionary

    def write_table(self):
        """
        Write columns with time and data into table.
        :return: self
        """
        self._write_time()
        self._write_data()
        return self

    def _write_time(self):
        """
        Write column with time into table.
        """
        self.worksheet.write(1, 0, 'Time')
        try:
            systime = [datetime.strptime(item, "%a %b %d %H:%M:%S %Y") for item in self.systime]
        except ValueError:
            systime = [datetime.strptime(item, "%Y.%m.%d %H:%M:%S") for item in self.systime]
        row = 2
        for time in systime:
            self.worksheet.write_datetime(row, 0, time)
            row += 1
        rows_amount = len(self.systime) + 2
        self._rows_amount = rows_amount

    def _write_data(self):
        """
        Go through dictionary with data and add columns with data into table in two ways depending on if data is nested.
        """
        column = 1
        for items in sorted(self.data):
            if isinstance(self.data[items], list):
                self._is_nested_dictionary = False
                self._write_list(column, items, self.data[items])
                self._columns_not_nested = len(self.data)
            else:
                column = self._write_dictionary(column, items, self.data[items])
                self._columns_nested.append(column)
            column += 1

    def _write_list(self, column, column_label, items):
        """
        Write one column with data into table in worksheet. Used if data is not nested.
        :param: column: Column number to add.
        :param: column_label: Column name to add.
        :param: items: Values to add in column.
        """
        self.worksheet.write(1, column, column_label)
        table = self._string_to_float(items)
        self.worksheet.write_column(2, column, table)

    def _write_dictionary(self, column, parameter, items):
        """
        Write parameter name and all columns with its data into table in worksheet. Used if data is nested.
        :param: column: Column number to add.
        :param: parameter: Parameter name to add, e.g. CPU1.
        :param: items: Dictionary with items and values to add in columns for parameter key.
        :return: column: Number of last column in series.
        """
        self.worksheet.write(0, column, parameter)
        for item in items:
            table = self._string_to_float(items[item])
            if table:
                self.worksheet.write(1, column, item)
                self.worksheet.write_column(2, column, table)
                column += 1
        return column

    @staticmethod
    def _string_to_float(data):
        """
        Convert type of data to float.
        :param: data: Array with values to convert.
        :return: table: Array with float values.
        """
        table = []
        try:
            table = [float(item) for item in data]
        except ValueError:
            pass
        return table
